  const record = Buffer.concat([pt, Buffer.from([2]), Buffer.alloc(padding)]);
  if (record.length + 16 > RECORD_SIZE) throw new Error('payload too large for one record');
  const cipher = crypto.createCipheriv('aes-128-gcm', cek, nonce);
  const ct = Buffer.concat([cipher.update(record), cipher.final(), cipher.getAuthTag()]);
  const header = Buffer.alloc(21);
  salt.copy(header, 0);
  header.writeUInt32BE(RECORD_SIZE, 16);
  header.writeUInt8(asPublic.length, 20);
  const body = Buffer.concat([header, asPublic, ct]);
